import { useEffect, useMemo, useRef, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Network, Users, Bug, Target, Globe, RefreshCw, Search, Filter } from "lucide-react";

// ── Types ──────────────────────────────────────────────────────────────────────
type NodeType = "actor" | "malware" | "ioc" | "cve" | "campaign" | "threat";

interface GraphNode {
  id: string;
  label: string;
  type: NodeType;
  weight: number;        // size multiplier (more connections = bigger)
  // Force-directed layout fields (mutable during simulation)
  x: number;
  y: number;
  vx: number;
  vy: number;
}

interface GraphEdge {
  source: string;
  target: string;
  relationship: string;
  confidence: number;
}

const NODE_STYLES: Record<NodeType, { color: string; bg: string; ring: string; icon: typeof Users }> = {
  actor:    { color: "#f87171", bg: "rgba(248,113,113,0.15)", ring: "#f87171", icon: Users },
  malware:  { color: "#a78bfa", bg: "rgba(167,139,250,0.15)", ring: "#a78bfa", icon: Bug },
  ioc:      { color: "#fbbf24", bg: "rgba(251,191,36,0.15)",  ring: "#fbbf24", icon: Target },
  cve:      { color: "#fb923c", bg: "rgba(251,146,60,0.15)",  ring: "#fb923c", icon: Bug },
  campaign: { color: "#34d399", bg: "rgba(52,211,153,0.15)",  ring: "#34d399", icon: Globe },
  threat:   { color: "#22d3ee", bg: "rgba(34,211,238,0.15)",  ring: "#22d3ee", icon: Target },
};

const NODE_SIZES: Record<NodeType, number> = {
  actor: 18, malware: 16, campaign: 16, ioc: 10, cve: 12, threat: 8,
};

// ── Build graph from DB tables ────────────────────────────────────────────────
function useThreatGraphData(typeFilter: NodeType | "all", search: string) {
  return useQuery({
    queryKey: ["threat_graph", typeFilter, search],
    queryFn: async (): Promise<{ nodes: GraphNode[]; edges: GraphEdge[] }> => {
      const [actorsRes, indicatorsRes, relationshipsRes, threatItemsRes] = await Promise.all([
        supabase.from("threat_actors").select("id,name,aliases,nation_state").limit(50),
        supabase.from("indicators").select("id,value,ioc_type,reputation,sighting_count,malware_families,threat_actors")
          .eq("reputation", "malicious").order("sighting_count", { ascending: false }).limit(80),
        supabase.from("relationships").select("source_type,source_id,target_type,target_id,relationship,confidence").limit(500),
        supabase.from("threat_items")
          .select("id,title,severity,threat_actors,malware_families,iocs,mitre_techniques")
          .in("severity", ["critical", "high"])
          .order("published_at", { ascending: false })
          .limit(40),
      ]);

      const actors = actorsRes.data ?? [];
      const indicators = indicatorsRes.data ?? [];
      const relationships = relationshipsRes.data ?? [];
      const threatItems = threatItemsRes.data ?? [];

      const nodes = new Map<string, GraphNode>();
      const edges: GraphEdge[] = [];

      // Random initial positions in a circle (will be force-laid-out later)
      const place = (i: number, total: number) => {
        const angle = (i / Math.max(total, 1)) * Math.PI * 2;
        return {
          x: 400 + Math.cos(angle) * 200 + (Math.random() - 0.5) * 50,
          y: 300 + Math.sin(angle) * 200 + (Math.random() - 0.5) * 50,
          vx: 0,
          vy: 0,
        };
      };

      // Add actors
      actors.forEach((a: any, i: number) => {
        nodes.set(`actor:${a.id}`, {
          id:     `actor:${a.id}`,
          label:  a.name,
          type:   "actor",
          weight: 1,
          ...place(i, actors.length),
        });
      });

      // Add indicators (IOCs)
      indicators.forEach((ind: any, i: number) => {
        const isHash = ind.ioc_type?.startsWith("hash");
        const isCVE  = ind.ioc_type === "cve";
        const type: NodeType = isCVE ? "cve" : "ioc";
        const label = isHash ? `${ind.value.slice(0, 12)}…` : ind.value.slice(0, 30);
        nodes.set(`indicator:${ind.id}`, {
          id:     `indicator:${ind.id}`,
          label,
          type,
          weight: Math.min(ind.sighting_count, 10),
          ...place(i + actors.length, indicators.length + actors.length),
        });

        // Edges from IOCs to actors (via threat_actors[] in indicator)
        for (const actorName of (ind.threat_actors ?? [])) {
          const actor = actors.find((a: any) =>
            a.name.toLowerCase() === actorName.toLowerCase() ||
            (a.aliases ?? []).some((al: string) => al.toLowerCase() === actorName.toLowerCase())
          );
          if (actor) {
            edges.push({
              source:        `indicator:${ind.id}`,
              target:        `actor:${actor.id}`,
              relationship:  "attributed_to",
              confidence:    Math.min(ind.sighting_count * 10, 95),
            });
          }
        }
      });

      // Add malware family pseudo-nodes (deduplicated)
      const malwareSet = new Set<string>();
      threatItems.forEach((t: any) => (t.malware_families ?? []).forEach((m: string) => malwareSet.add(m)));
      indicators.forEach((i: any) => (i.malware_families ?? []).forEach((m: string) => malwareSet.add(m)));
      [...malwareSet].forEach((mname, i) => {
        nodes.set(`malware:${mname}`, {
          id:     `malware:${mname}`,
          label:  mname,
          type:   "malware",
          weight: 2,
          ...place(i + actors.length + indicators.length, actors.length + indicators.length + malwareSet.size),
        });
      });

      // Edges from malware → actors and malware → IOCs (text matching)
      threatItems.forEach((t: any) => {
        const itemActors = t.threat_actors ?? [];
        const itemMalware = t.malware_families ?? [];
        for (const m of itemMalware) {
          if (!nodes.has(`malware:${m}`)) continue;
          for (const an of itemActors) {
            const actor = actors.find((a: any) =>
              a.name.toLowerCase() === an.toLowerCase() ||
              (a.aliases ?? []).some((al: string) => al.toLowerCase() === an.toLowerCase())
            );
            if (actor) {
              edges.push({
                source: `malware:${m}`,
                target: `actor:${actor.id}`,
                relationship: "used_by",
                confidence: 70,
              });
            }
          }
        }
      });

      // Edges from explicit relationships table
      for (const r of relationships) {
        const srcKey = `${r.source_type}:${r.source_id}`;
        const tgtKey = `${r.target_type === "actor" ? "actor" : r.target_type}:${r.target_id}`;
        if (nodes.has(srcKey) && nodes.has(tgtKey)) {
          edges.push({
            source: srcKey,
            target: tgtKey,
            relationship: r.relationship,
            confidence: r.confidence ?? 50,
          });
        }
      }

      // Boost weight by edge count
      const edgeCounts = new Map<string, number>();
      for (const e of edges) {
        edgeCounts.set(e.source, (edgeCounts.get(e.source) ?? 0) + 1);
        edgeCounts.set(e.target, (edgeCounts.get(e.target) ?? 0) + 1);
      }
      for (const [id, count] of edgeCounts) {
        const node = nodes.get(id);
        if (node) node.weight = 1 + Math.log2(count + 1);
      }

      // Filter nodes with no connections (lonely)
      const connected = new Set([...edgeCounts.keys()]);
      let allNodes = [...nodes.values()].filter(n => connected.has(n.id) || n.type === "actor");

      // Apply type filter and search
      if (typeFilter !== "all") {
        allNodes = allNodes.filter(n => n.type === typeFilter);
      }
      if (search) {
        const q = search.toLowerCase();
        allNodes = allNodes.filter(n => n.label.toLowerCase().includes(q));
      }

      const allowedIds = new Set(allNodes.map(n => n.id));
      const filteredEdges = edges.filter(e => allowedIds.has(e.source) && allowedIds.has(e.target));

      return { nodes: allNodes, edges: filteredEdges };
    },
    staleTime: 5 * 60_000,
  });
}

// ── Force-directed layout simulation ──────────────────────────────────────────
function runSimulation(nodes: GraphNode[], edges: GraphEdge[], iterations = 200) {
  const W = 800, H = 600;
  const center = { x: W / 2, y: H / 2 };

  const nodeMap = new Map(nodes.map(n => [n.id, n]));

  for (let iter = 0; iter < iterations; iter++) {
    const alpha = 1 - iter / iterations;

    // Repulsion (every pair pushes apart)
    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < nodes.length; j++) {
        const a = nodes[i], b = nodes[j];
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const dist = Math.max(Math.sqrt(dx * dx + dy * dy), 1);
        const force = 1500 / (dist * dist);
        a.vx -= (dx / dist) * force * alpha;
        a.vy -= (dy / dist) * force * alpha;
        b.vx += (dx / dist) * force * alpha;
        b.vy += (dy / dist) * force * alpha;
      }
    }

    // Attraction (edges pull connected nodes together)
    for (const e of edges) {
      const a = nodeMap.get(e.source);
      const b = nodeMap.get(e.target);
      if (!a || !b) continue;
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const dist = Math.max(Math.sqrt(dx * dx + dy * dy), 1);
      const targetDist = 100;
      const force = (dist - targetDist) * 0.05;
      a.vx += (dx / dist) * force * alpha;
      a.vy += (dy / dist) * force * alpha;
      b.vx -= (dx / dist) * force * alpha;
      b.vy -= (dy / dist) * force * alpha;
    }

    // Center gravity
    for (const n of nodes) {
      n.vx += (center.x - n.x) * 0.005 * alpha;
      n.vy += (center.y - n.y) * 0.005 * alpha;
    }

    // Apply velocity with damping
    for (const n of nodes) {
      n.vx *= 0.7;
      n.vy *= 0.7;
      n.x = Math.max(20, Math.min(W - 20, n.x + n.vx));
      n.y = Math.max(20, Math.min(H - 20, n.y + n.vy));
    }
  }
}

// ── Main page component ───────────────────────────────────────────────────────
export default function ThreatGraph() {
  const [typeFilter, setTypeFilter] = useState<NodeType | "all">("all");
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState<GraphNode | null>(null);
  const [hovered, setHovered]   = useState<GraphNode | null>(null);
  const svgRef = useRef<SVGSVGElement>(null);

  const { data, isLoading, refetch, isFetching } = useThreatGraphData(typeFilter, search);

  // Run force-directed layout once data arrives
  const laidOut = useMemo(() => {
    if (!data?.nodes.length) return { nodes: [], edges: [] };
    const nodes = data.nodes.map(n => ({ ...n }));   // clone — don't mutate query cache
    runSimulation(nodes, data.edges);
    return { nodes, edges: data.edges };
  }, [data]);

  const nodeMap = useMemo(() => new Map(laidOut.nodes.map(n => [n.id, n])), [laidOut]);

  // Stats
  const stats = useMemo(() => {
    const counts: Record<NodeType, number> = { actor: 0, malware: 0, ioc: 0, cve: 0, campaign: 0, threat: 0 };
    for (const n of laidOut.nodes) counts[n.type]++;
    return { ...counts, edges: laidOut.edges.length };
  }, [laidOut]);

  return (
    <div className="container mx-auto px-4 py-8 max-w-screen-2xl">
      <div className="mb-6">
        <h1 className="flex items-center gap-3 text-3xl font-bold tracking-tight">
          <Network className="h-8 w-8 text-primary" />
          Threat Knowledge Graph
        </h1>
        <p className="mt-1 text-muted-foreground text-sm">
          Force-directed visualization of threat actors, malware families, IOCs, CVEs, and campaigns. Edges represent verified relationships from the correlation engine.
        </p>
      </div>

      {/* Stats bar */}
      <div className="grid grid-cols-3 md:grid-cols-6 gap-2 mb-4">
        {(["actor", "malware", "ioc", "cve", "campaign"] as NodeType[]).map(t => (
          <Card key={t} className="bg-card/40 border-border/40">
            <CardContent className="p-2 text-center">
              <div className="text-lg font-bold" style={{ color: NODE_STYLES[t].color }}>
                {stats[t]}
              </div>
              <div className="text-[10px] text-muted-foreground capitalize">{t}s</div>
            </CardContent>
          </Card>
        ))}
        <Card className="bg-card/40 border-border/40">
          <CardContent className="p-2 text-center">
            <div className="text-lg font-bold text-primary">{stats.edges}</div>
            <div className="text-[10px] text-muted-foreground">edges</div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap items-center gap-2 mb-4">
        <div className="relative flex-1 min-w-48 max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search nodes (actor, IOC, malware…)"
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="pl-9 h-8 text-sm"
          />
        </div>
        <div className="flex items-center gap-1">
          <Filter className="h-3.5 w-3.5 text-muted-foreground" />
          {(["all", "actor", "malware", "ioc", "cve"] as const).map(t => (
            <Button
              key={t}
              size="sm"
              variant={typeFilter === t ? "default" : "outline"}
              onClick={() => setTypeFilter(t)}
              className="h-7 text-xs capitalize"
            >
              {t}
            </Button>
          ))}
        </div>
        <Button size="sm" variant="outline" onClick={() => refetch()} className="h-7 text-xs gap-1.5 ml-auto">
          <RefreshCw className={`h-3 w-3 ${isFetching ? "animate-spin" : ""}`} />
          Refresh
        </Button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-4">
        {/* Graph SVG */}
        <Card className="lg:col-span-3 border-border/40 overflow-hidden">
          <CardContent className="p-0">
            {isLoading ? (
              <div className="h-[600px] flex items-center justify-center text-muted-foreground text-sm">
                Building graph from DB…
              </div>
            ) : laidOut.nodes.length === 0 ? (
              <div className="h-[600px] flex items-center justify-center text-muted-foreground text-sm">
                No relationships found. Run feed ingestion to populate.
              </div>
            ) : (
              <svg
                ref={svgRef}
                viewBox="0 0 800 600"
                className="w-full bg-gradient-to-br from-card/30 to-background"
                style={{ height: "600px" }}
                onClick={() => setSelected(null)}
              >
                {/* Edges */}
                <g>
                  {laidOut.edges.map((e, i) => {
                    const a = nodeMap.get(e.source);
                    const b = nodeMap.get(e.target);
                    if (!a || !b) return null;
                    const isHighlighted = hovered && (hovered.id === e.source || hovered.id === e.target);
                    return (
                      <line
                        key={i}
                        x1={a.x}
                        y1={a.y}
                        x2={b.x}
                        y2={b.y}
                        stroke={isHighlighted ? "#22d3ee" : "hsl(var(--border))"}
                        strokeOpacity={isHighlighted ? 0.8 : 0.25}
                        strokeWidth={isHighlighted ? 1.5 : 0.6}
                      />
                    );
                  })}
                </g>
                {/* Nodes */}
                <g>
                  {laidOut.nodes.map(n => {
                    const style = NODE_STYLES[n.type];
                    const r = NODE_SIZES[n.type] * (1 + (n.weight - 1) * 0.15);
                    const isFocused = selected?.id === n.id || hovered?.id === n.id;
                    return (
                      <g
                        key={n.id}
                        transform={`translate(${n.x},${n.y})`}
                        style={{ cursor: "pointer" }}
                        onClick={(e) => { e.stopPropagation(); setSelected(n); }}
                        onMouseEnter={() => setHovered(n)}
                        onMouseLeave={() => setHovered(null)}
                      >
                        <circle
                          r={r + (isFocused ? 4 : 0)}
                          fill={style.bg}
                          stroke={style.ring}
                          strokeWidth={isFocused ? 2.5 : 1.2}
                          opacity={hovered && hovered.id !== n.id && !laidOut.edges.some(e => (e.source === hovered.id && e.target === n.id) || (e.target === hovered.id && e.source === n.id)) ? 0.3 : 1}
                        />
                        {(isFocused || r > 14) && (
                          <text
                            y={r + 12}
                            textAnchor="middle"
                            className="fill-foreground text-[10px] font-medium pointer-events-none"
                            style={{ filter: "drop-shadow(0 1px 2px rgba(0,0,0,0.8))" }}
                          >
                            {n.label.slice(0, 24)}
                          </text>
                        )}
                      </g>
                    );
                  })}
                </g>
              </svg>
            )}
          </CardContent>
        </Card>

        {/* Side panel */}
        <Card className="lg:col-span-1 border-border/40">
          <CardContent className="p-4">
            {selected ? (
              <div className="space-y-3">
                <div className="flex items-center gap-2">
                  <div
                    className="h-3 w-3 rounded-full"
                    style={{ background: NODE_STYLES[selected.type].color }}
                  />
                  <Badge variant="outline" className="text-[9px] uppercase">
                    {selected.type}
                  </Badge>
                </div>
                <h3 className="font-semibold text-sm break-all">{selected.label}</h3>
                <div className="space-y-1 text-xs text-muted-foreground">
                  <p>Connections: <span className="text-foreground font-medium">{
                    laidOut.edges.filter(e => e.source === selected.id || e.target === selected.id).length
                  }</span></p>
                  <p>Weight: <span className="text-foreground font-medium">{selected.weight.toFixed(1)}</span></p>
                </div>
                <div className="border-t border-border/40 pt-3">
                  <p className="text-[10px] uppercase tracking-wide text-muted-foreground mb-2">Linked nodes</p>
                  <div className="space-y-1 max-h-64 overflow-auto">
                    {laidOut.edges
                      .filter(e => e.source === selected.id || e.target === selected.id)
                      .map((e, i) => {
                        const otherId = e.source === selected.id ? e.target : e.source;
                        const other = nodeMap.get(otherId);
                        if (!other) return null;
                        return (
                          <button
                            key={i}
                            onClick={() => setSelected(other)}
                            className="w-full flex items-center gap-2 p-1.5 rounded hover:bg-muted/40 transition text-left"
                          >
                            <div
                              className="h-2 w-2 rounded-full shrink-0"
                              style={{ background: NODE_STYLES[other.type].color }}
                            />
                            <span className="text-xs truncate flex-1">{other.label}</span>
                            <Badge variant="outline" className="text-[8px] shrink-0">
                              {e.relationship}
                            </Badge>
                          </button>
                        );
                      })}
                  </div>
                </div>
              </div>
            ) : (
              <div className="space-y-3">
                <h3 className="text-sm font-semibold">Legend</h3>
                {(Object.keys(NODE_STYLES) as NodeType[]).map(t => {
                  const Icon = NODE_STYLES[t].icon;
                  return (
                    <div key={t} className="flex items-center gap-2 text-xs">
                      <div
                        className="h-3 w-3 rounded-full shrink-0"
                        style={{ background: NODE_STYLES[t].bg, border: `2px solid ${NODE_STYLES[t].ring}` }}
                      />
                      <Icon className="h-3 w-3 text-muted-foreground" />
                      <span className="capitalize">{t}</span>
                    </div>
                  );
                })}
                <p className="text-[10px] text-muted-foreground border-t border-border/40 pt-3">
                  Click any node to inspect connections. Hover to highlight neighbors. Edges are drawn from verified correlations in the relationships table.
                </p>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}
